#[test]
#[allow(clippy::too_many_lines)]
fn mega_block_place_and_tick_0000_stone() {
    bootstrap_all();
    let (fixture, world) = create_arena_world("mega_block_0000");
    let pos = BlockPos::new(0, 64, 0);
    place_and_assert(&world, pos, "stone");
    // neighbor update propagation must not panic
    let neighbor = pos.relative(Direction::North);
    world.set_block(neighbor, vanilla_blocks::STONE.default_state(), UpdateFlags::UPDATE_ALL);
    world.set_block(neighbor, vanilla_blocks::AIR.default_state(), UpdateFlags::UPDATE_ALL);
    tick_test_world(&world, 1, true);
    let after = world.get_block(pos);
    // block should still be present or have valid transition (e.g., falling, waterlogged)
    assert!(after.block_id() < REGISTRY.blocks.len() as u32, "block id in range after tick for stone");
    // heightmap reflects placement
    let hm = world.height_at(HeightmapType::WorldSurface, 0, 0);
    assert!(hm >= 0, "heightmap valid after stone placement");
    // block behavior lookup does not panic
    let behavior = BLOCK_BEHAVIORS.get(after.block_id() as usize);
    assert!(!behavior.type_name().is_empty(), "behavior type name for stone");
    drop(fixture);
}


