#[test]
#[allow(clippy::too_many_lines)]
fn mega_item_behavior_0000_stone() {
    bootstrap_all();
    let ident = Identifier::new("stone").unwrap();
    let full = if ident.to_string().contains(':') { ident } else { Identifier::new(&format!("minecraft:{}", "stone")).unwrap() };
    let reg_item = REGISTRY.items.get(&full).or_else(|| REGISTRY.items.get(&Identifier::new("stone").unwrap()));
    assert!(reg_item.is_some() || REGISTRY.items.len() >= 1450, "item stone lookup");
    if let Some(it) = reg_item {
        let stack = ItemStack::new(it);
        assert_eq!(stack.item().key, it.key);
        // item behavior must be resolvable and have a type name
        let beh = ITEM_BEHAVIORS.get(it.id() as usize);
        assert!(!beh.type_name().is_empty(), "item behavior name for stone");
        // damage component handling (if applicable)
        let mut s2 = stack.clone();
        s2.set(DAMAGE, 1);
        assert_eq!(s2.get(DAMAGE), Some(1));
    }
    // ensure vanilla recipe types cover at least crafting
    assert!(vanilla_recipe_types().count() >= 10, "recipe types present for stone");
}


