#[test]
#[allow(clippy::too_many_lines)]
fn mega_redstone_0000_piston_extends() {
    bootstrap_all();
    let (fixture, world) = create_arena_world("redstone_0000_piston_extends");
    let base = BlockPos::new(0, 64, 0);
    let pos_a = base;
    let pos_b = base.relative(Direction::East);
    place_and_assert(&world, pos_a, "piston");
    place_and_assert(&world, pos_b, "stone");
    // tick a few times to allow scheduled ticks and neighbor updates
    for tick in 1..=5u64 {
        tick_test_world(&world, tick, true);
    }
    // block entities should be ticked if present
    assert!(world.get_block(pos_a).block_id() < REGISTRY.blocks.len() as u32);
    assert!(world.get_block(pos_b).block_id() < REGISTRY.blocks.len() as u32);
    // hopper special: if involved, ensure its block entity exists
    if "piston" == "hopper" || "stone" == "hopper" {
        // hopper block entity tick is covered by world tick, no panic = success
    }
    drop(fixture);
}


