#[test]
#[allow(clippy::too_many_lines)]
fn mega_container_menu_0000_chest() {
    bootstrap_all();
    assert_eq!(REGISTRY.menu_types.len(), 25);
    let mut container = SimpleContainer::new(27);
    let stack = ItemStack::new(&vanilla_items::STONE);
    container.set(0, stack.clone());
    assert_eq!(container.get(0).item().key, vanilla_items::STONE.key);
    // menu kinds must be resolvable via registry
    assert!(REGISTRY.menu_types.len() >= 25);
    // container lock
    let cref = ContainerRef::new(Arc::new(SyncMutex::new(container)));
    assert!(cref.lock().get(0).item().key == vanilla_items::STONE.key);
}


