#[test]
#[allow(clippy::too_many_lines)]
fn mega_sculk_warden_0000() {
    bootstrap_all();
    let (fixture, world) = create_arena_world("sculk_0000");
    let sensor_pos = BlockPos::new(0, 64, 0);
    let shrieker_pos = BlockPos::new(2, 64, 0);
    place_and_assert(&world, sensor_pos, "sculk_sensor");
    place_and_assert(&world, shrieker_pos, "sculk_shrieker");
    tick_test_world(&world, 1, true);
    // vibration frequency and redstone strength helpers
    let freq = vibration_frequency(&vanilla_game_events::BLOCK_PLACE);
    assert!(freq >= 1 && freq <= 15, "frequency in range {}", freq);
    for d in [0, 4, 8, 15] {
        let s = redstone_strength_for_distance(d);
        assert!(s <= 15, "strength {} at distance {}", s, d);
    }
    // Warden sonic boom damage source exists
    let _warden = WardenEntity::new(&vanilla_entities::WARDEN, next_entity_id(), DVec3::new(0.5, 65.0, 0.5), Arc::downgrade(&world));
    assert!(REGISTRY.entity_types.get(&Identifier::new("minecraft:warden").unwrap()).is_some());
    drop(fixture);
}


