#[test]
#[allow(clippy::too_many_lines)]
fn mega_maps_bans_recipes_loot_0000() {
    bootstrap_all();
    // bans
    let bans = BanList::new();
    let entry = BanEntry::address(IpAddr::V4(Ipv4Addr::new(127,0,0,1)), "127.0.0.1", "test", "console", 1_000, None);
    bans.ban_address(entry);
    assert!(bans.is_address_banned(IpAddr::V4(Ipv4Addr::new(127,0,0,1)), 2_000));
    assert!(bans.pardon_address(IpAddr::V4(Ipv4Addr::new(127,0,0,1))));
    assert!(!bans.is_address_banned(IpAddr::V4(Ipv4Addr::new(127,0,0,1)), 2_000));
    // recipes
    assert!(vanilla_recipe_types().count() >= 10);
    // loot: check loot tables registry has entries
    assert!(REGISTRY.loot_tables.len() >= 1000);
    // combat: damage source
    let src = DamageSource::environment(&vanilla_damage_types::GENERIC);
    let _ = src;
    // vehicles: minecart
    let (fixture, world) = create_arena_world("vehicle_0000");
    let cart = MinecartEntity::new(&vanilla_entities::MINECART, next_entity_id(), DVec3::new(0.5,65.0,0.5), Arc::downgrade(&world));
    assert!(world.try_add_entity(Arc::clone(&cart) as _).is_ok());
    tick_test_world(&world, 1, true);
    let _chest_cart = ChestMinecartEntity::new(&vanilla_entities::CHEST_MINECART, next_entity_id(), DVec3::new(1.5,65.0,0.5), Arc::downgrade(&world));
    let _furnace_cart = FurnaceMinecartEntity::new(&vanilla_entities::FURNACE_MINECART, next_entity_id(), DVec3::new(2.5,65.0,0.5), Arc::downgrade(&world));
    // filled map
    let map_stack = ItemStack::new(&vanilla_items::FILLED_MAP);
    let _ = map_stack;
    drop(fixture);
}


