#[test]
#[allow(clippy::too_many_lines)]
fn mega_worldgen_0000_overworld() {
    bootstrap_all();
    // biome registry must be populated
    assert!(REGISTRY.biomes.len() >= 60, "biomes for overworld");
    // heightmap types
    let hm = HeightmapType::WorldSurface;
    let _ = hm;
    // chunk pos math
    let cp = ChunkPos::new(0, 0);
    assert_eq!(cp.x, 0);
    // worldgen stages: terrain / features / light are covered by chunk-stage hashes, here we just ensure world creation works
    let (fixture, world) = create_arena_world("worldgen_0000_overworld");
    // ensure dimension type exists
    let dim_type = REGISTRY.dimension_types.get(&Identifier::new("minecraft:overworld").unwrap());
    assert!(dim_type.is_some() || REGISTRY.dimension_types.len() >= 4);
    tick_test_world(&world, 1, true);
    // persistence: chunk saver uses NBT, ensure empty NBT roundtrips
    let mut nbt = NbtCompound::new();
    nbt.insert("test", simdnbt::owned::NbtTag::Int(0));
    assert_eq!(nbt.get::<i32>("test"), Some(&0));
    drop(fixture);
}


