#[test]
#[allow(clippy::too_many_lines)]
fn mega_physics_tick_mspt_ram_0000() {
    bootstrap_all();
    let (fixture, world) = create_arena_world("physics_0000");
    // spawn falling block entity and tick
    let start = Instant::now();
    for tick in 1..=20u64 {
        let ts = Instant::now();
        tick_test_world(&world, tick, true);
        world.waypoints.tick(&world);
        world.raids.tick(&world);
        let micros = ts.elapsed().as_micros();
        assert!(micros < 250_000, "tick {} mspt under 250ms, got {}us", tick, micros);
    }
    assert!(start.elapsed().as_millis() < 2_000, "20 ticks under 2s for mspt headroom");
    // physics: push_entities_up etc. indirectly via tick
    // scheduled ticks
    let pos = BlockPos::new(0,64,0);
    world.set_block(pos, vanilla_blocks::SAND.default_state(), UpdateFlags::UPDATE_ALL);
    tick_test_world(&world, 21, true);
    assert!(world.get_block(pos.below()).block_id() < REGISTRY.blocks.len() as u32);
    // ScheduledPlayPacket size invariant (hot path)
    assert!(size_of::<ScheduledPlayPacket>() <= 96, "packet size invariant");
    // entity manager spatial query
    let aabb = WorldAabb { min: DVec3::new(0.0,64.0,0.0), max: DVec3::new(16.0,70.0,16.0) };
    let _ents = world.entities.within_aabb(&aabb);
    drop(fixture);
}


