fn mega_packet_protocol_0047() {
    bootstrap_all();
    // protocol 777
    assert_eq!(CURRENT_MC_PROTOCOL, 777);
    // packet id decoding helper works for dummy packet
    let dummy = EncodedPacket { encoded_data: vec![0x02, 0x00], protocol: ConnectionProtocol::Play };
    let id = decode_packet_id(&dummy);
    assert!(id >= 0, "packet id {} decoded", id);
    // varint roundtrip
    let mut buf = Vec::new();
    VarInt(47).write(&mut buf).unwrap();
    let mut cursor = Cursor::new(buf.as_slice());
    let got = VarInt::read(&mut cursor).unwrap();
    assert_eq!(got.0, 47);
    // waypoint icon
    let icon = if 47 % 2 == 0 { WaypointIcon::Village } else { WaypointIcon::Death };
    let _ = icon;
    // command exec helper exists
    let _ = exec_command as fn(&Arc<Server>, CommandSender, &str) -> Result<(bool,i32), String>;
    // permission index
    let mut idx = PermissionSubjectIndex::new();
    let state = PermissionSubjectState { permissions: PermissionSet::default(), metadata: PermissionMetadataSet::default() };
    let _ = idx;
    let _ = state;
    // server config defaults
    let cfg = ResolvedDomainConfig::default();
    let _ = cfg;
}


